"""Optional offline Speediance strength-source FIT generated by this exporter.

A previously created direct Speediance FIT is enough to recover completed
strength SET messages, actual weights and summary HR when the unofficial
Speediance cloud detail endpoint is temporarily unavailable.
FIT source stays unchanged; never logs path, set weights, heart rates or IDs.
"""
from datetime import timezone
from pathlib import Path

from fitwriter import stamp
from garmin_fit_reader import read_garmin_activity
from garmin_fit_overlay import parse_fit_wire, _get_numeric
from garmin_local_fit import LocalGarminFitError, match_local_garmin_fit


MAX_BYTES = 24 * 1024 * 1024


class SavedSpeedianceFitError(ValueError):
    """Safe, user-readable error for incompatible local backup FIT files."""


def load_saved_speediance_fit(workout, path):
    """Return (workout data reconstructed from FIT, original FIT bytes).

    Only accept a direct activity that this exporter wrote for the same
    Speediance training ID, to prevent merging an unrelated training.
    Preserve SET messages byte-for-byte via garmin_fit_overlay.
    """
    p = Path(path)
    if p.suffix.lower() != ".fit":
        raise SavedSpeedianceFitError(
            "Bitte eine zuvor mit Speediance FIT Exporter erstellte .fit-Datei wählen"
        )
    try:
        size = p.stat().st_size
        if not 16 <= size <= MAX_BYTES:
            raise SavedSpeedianceFitError("Die Speediance-FIT hat eine ungültige Größe")
        contents = p.read_bytes()
    except OSError:
        raise SavedSpeedianceFitError("Speediance-FIT kann nicht gelesen werden") from None
    if len(contents) != size:
        raise SavedSpeedianceFitError("Speediance-FIT wurde beim Lesen verändert")

    try:
        chunks = parse_fit_wire(contents)
        identities = [x for x in chunks if x["kind"] == "data" and x["global"] == 0]
        sessions = [x for x in chunks if x["kind"] == "data" and x["global"] == 18]
        strength_sets = [x for x in chunks if x["kind"] == "data" and x["global"] == 225]
        if len(identities) != 1 or len(sessions) != 1 or not strength_sets:
            raise SavedSpeedianceFitError(
                "Speediance-FIT muss eine einzelne Aktivität mit ausgeführten Sätzen enthalten"
            )
        identity = identities[0]
        if (_get_numeric(identity, 0) != 4
                or _get_numeric(identity, 1) != 255):
            raise SavedSpeedianceFitError(
                "Bitte einen direkten Speediance-FIT-Export verwenden, nicht die Garmin-Originaldatei"
            )
        expected_id = int(workout["training_id"]) & 0xFFFFFFFF or 1
        if _get_numeric(identity, 3) != expected_id:
            raise SavedSpeedianceFitError(
                "Die Speediance-FIT gehört zu einer anderen Trainingseinheit"
            )
        if (_get_numeric(sessions[0], 5) != 10
                or _get_numeric(sessions[0], 6) != 20):
            raise SavedSpeedianceFitError(
                "Speediance-FIT enthält kein Krafttraining"
            )
        metrics = read_garmin_activity(contents)
        # Same strict start/duration match as the manually selected Garmin.
        match_local_garmin_fit(workout, metrics)
    except SavedSpeedianceFitError:
        raise
    except (LocalGarminFitError, ValueError, TypeError, OverflowError):
        raise SavedSpeedianceFitError(
            "Speediance-FIT passt nicht zur ausgewählten Einheit oder ist beschädigt"
        ) from None

    session_start = metrics["start"]
    if session_start is None:
        raise SavedSpeedianceFitError("Speediance-FIT hat keinen Trainingsbeginn")
    start = session_start.astimezone(timezone.utc)
    exercises = [{
        "name": "Gespeicherte Speediance-Sätze",
        "sets": [
            {
                "reps": int(_get_numeric(item, 3) or 0),
                "weight": float(_get_numeric(item, 4) or 0) / 16,
                "seconds": float(_get_numeric(item, 0) or 0) / 1000,
                "weight_already_total": True,
            } for item in strength_sets
        ],
    }]
    bpm_points = [
        (int(round((t - start).total_seconds())), bpm)
        for t, bpm in metrics["heart_rate_records"]
        if 0 <= (t - start).total_seconds() <= metrics["duration_seconds"]
    ]
    detail = {
        "training_id": workout["training_id"],
        "day": start.date().isoformat(),
        "started_at": start.isoformat(),
        "duration_seconds": metrics["duration_seconds"],
        "duration_min": metrics["duration_seconds"] / 60,
        "calories": metrics["calories"],
        "heart_rate_summary": metrics["heart_rate_summary"],
        "heart_rate_points": bpm_points,
        "exercises": exercises,
        "unit": "kg",
    }
    return detail, contents
